#nullable enable // autogenerated

using MVZ2;
using MVZ2.Managers;
using MVZ2.Sprites;
using MVZ2Logic.Options;
using MVZ2Logic.UI;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    public class PoolColorSetter : MonoBehaviour
    {
        private void OnEnable()
        {
            if (!poolRenderer)
                return;
            var main = MainManager.Instance;
            var color = main.OptionsManager.HasBloodAndGore() ? normalColor : censoredColor;
            poolRenderer.color = color;
        }
        [SerializeField]
        private SpriteRendererResolver poolRenderer = null!;
        [SerializeField]
        private Color normalColor;
        [SerializeField]
        private Color censoredColor;
    }
}
